import {esc,money} from '../config.mjs';
export const mainRoutes=[['overview','Início','home',''],['purchases','Compras e mensagens','message',''],['sponsors','Empresas','company',''],['finance','Financeiro','finance',''],['management','Gestão','settings','']];
export function primaryControlRoute(route){if(['overview','sponsors','finance','management'].includes(route))return route;if(['purchases','all','review','ready','queue','refund','published','rejected','community'].includes(route))return'purchases';if(route==='recovery')return'finance';return'management'}
export const managementItems=[['content','Conteúdo e LIVE','Vídeo em destaque, link da LIVE, assunto e programação.'],['notifications','Notificações do app','Criar aviso, conferir o público e acompanhar os envios.'],['reactivation','Retorno automático','Ausências de 48h, retornos, falhas e cancelamentos.'],['general','Preços e disponibilidade','Valores, disponibilidade das mensagens e controles gerais.'],['senders','Remetentes · 48h','Consultar nome completo, telefone e IP com acesso registrado.'],['data','Dados e limpeza','Conferir vencidos, automatizar limpeza e preservar pendências.'],['cities','Cidades e ofertas','Acompanhar empresas e audiência por região.'],['team','Acesso da equipe','Conta conectada e permissões da equipe.'],['trash','Lixeira','Revisar registros arquivados e restaurar quando permitido.']];
export function managementMarkup(){return `<section><div class="control-page-head"><div><h1>Gestão</h1><p>Comandos do app, organizados por assunto.</p></div></div><div class="management-grid">${managementItems.map(([route,title,text])=>`<button class="management-card" data-control-route="${route}"><strong>${title}</strong><span>${text}</span><b aria-hidden="true">→</b></button>`).join('')}</div><details class="paper control-advanced"><summary>Programação avançada e testes</summary><p>Ferramentas técnicas e simulações ficam separadas da operação diária.</p><div class="actions"><button class="btn secondary" data-control-route="administrative">Programação e laboratório</button><button class="btn secondary" data-control-route="episode">Editor de episódio</button></div></details></section>`}
const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
export function operationRecords(data,{includeCompanies=false}={}){return [...(data.orders||[]).map(r=>({...r,kind:'video',buyer:r.name,route:'all'})),...(data.communityMessages||[]).map(r=>({...r,kind:r.destination==='live'?'live':'community',buyer:r.member_name,route:'community'})),...(includeCompanies?data.sponsors||[]:[]).map(r=>({...r,kind:'company',buyer:r.company_name,route:'sponsors'}))]}
export function operationStatus(r){if(r.payment_hold)return'Pagamento em atenção';if(r.payment==='refunded')return'Devolvido';if(r.review==='rejected')return r.payment==='confirmed'?'Devolução pendente':'Recusado';if(r.payment!=='confirmed')return'Aguardando pagamento';if(r.review!=='approved')return'Aguardando análise';if(r.hidden_at||r.archived_at)return'Fora de exibição';if(r.kind==='video')return r.delivery==='published'?'Veiculado no vídeo':'Na fila de edição';if(r.kind==='live')return r.live_status==='read'?'Leitura registrada':'Na fila da LIVE';if(r.expires_at&&Date.parse(r.expires_at)<=Date.now())return'Exibição encerrada';return r.published_at||r.starts_at?'Publicado':'Aprovado e pago'}
export function selectOperations(data,state){const q=normalize(state.query),rows=operationRecords(data,{includeCompanies:Boolean(q)&&state.kind==='all'}).filter(r=>{
 if(state.kind!=='all'&&r.kind!==state.kind)return false;
 if(state.payment==='confirmed'&&r.payment!=='confirmed'||state.payment==='pending'&&r.payment!=='pending'||state.payment==='attention'&&!r.payment_hold&&!(r.payment==='confirmed'&&r.review==='rejected'))return false;
 if(state.status==='review'&&r.review!=='pending'||state.status==='published'&&!(r.delivery==='published'||r.live_status==='read'||r.kind==='community'&&r.published_at&&!r.hidden_at&&Date.parse(r.expires_at)>Date.now()||r.kind==='company'&&r.starts_at&&Date.parse(r.starts_at)<=Date.now()&&Date.parse(r.expires_at)>Date.now()&&!r.archived_at&&!r.payment_hold)||state.status==='queue'&&!(r.payment==='confirmed'&&r.review==='approved'&&!r.payment_hold&&!r.hidden_at&&!r.archived_at&&(r.kind==='video'&&r.delivery!=='published'||r.kind==='live'&&r.live_status!=='read')))return false;
 return !q||normalize([r.buyer,r.code,r.member_username,r.social_handle,r.company_name,r.contact_name,r.city].join(' ')).includes(q);
 }).sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at)||String(a.code).localeCompare(String(b.code)));return{rows:rows.slice(Math.max(0,state.page||0)*50,(Math.max(0,state.page||0)+1)*50),total:rows.length}}
const kindLabel={video:'Vídeo oficial',community:'Comunidade',live:'LIVE',company:'Empresa'};
export function operationRowsMarkup(rows){return rows.map(r=>`<article class="operation-row" id="purchase-${esc(r.id)}"><div><span class="badge">${kindLabel[r.kind]}</span><strong>${esc(r.buyer||'Nome não informado')}</strong><small>${esc(r.code)} · ${esc(r.created_at?new Date(r.created_at).toLocaleString('pt-BR'):'Data indisponível')}</small></div><div><strong>${money(r.price_cents)}</strong><small>${r.payment==='confirmed'?'Pagamento confirmado':r.payment==='refunded'?'Pagamento devolvido':'Sem pagamento confirmado'}</small></div><div><strong>${esc(operationStatus(r))}</strong><small>${esc(r.kind==='company'?[r.city,r.state_code].filter(Boolean).join(' / '):r.kind==='video'?r.episode||'Vídeo oficial':kindLabel[r.kind])}</small></div><button class="btn secondary" data-open-operation="${esc(r.id)}" data-operation-kind="${r.kind}">${r.kind==='company'?'Ver empresa e ações':r.review==='pending'&&r.payment==='confirmed'?'Revisar mensagem':r.kind==='live'&&r.payment==='confirmed'&&r.live_status==='queued'?'Abrir fila de leitura':'Ver detalhes e ações'}</button></article>`).join('')||'<div class="empty">Nenhum pedido nesta seleção. Altere os filtros ou confira os envios sem pagamento.</div>'}
export function mountPurchases(host,data,state,onOpen){
 let disposed=false;host.innerHTML=`<section><div class="control-page-head"><div><h1>Compras e mensagens</h1><p>Quem comprou, o que enviou e qual é o próximo passo.</p></div><button class="btn secondary" data-control-route="senders">Consultar remetentes · 48h</button></div><div class="purchase-kind-tabs" role="group" aria-label="Destino da mensagem">${[['all','Todas'],['video','Vídeo oficial'],['community','Comunidade'],['live','LIVE']].map(([kind,label])=>`<button class="btn secondary" data-purchase-kind="${kind}" aria-pressed="${state.kind===kind}">${label}</button>`).join('')}</div><form class="purchase-filters" data-purchase-filters><label>Buscar nome, empresa ou código<input name="query" maxlength="120" value="${esc(state.query||'')}" placeholder="Digite para localizar"></label><label>Pagamento<select name="payment">${[['confirmed','Compras confirmadas'],['pending','Sem pagamento confirmado'],['attention','Com problema ou devolução'],['all','Todos os pagamentos']].map(([v,l])=>`<option value="${v}" ${state.payment===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Andamento<select name="status">${[['all','Todos os andamentos'],['review','Aguardando análise'],['queue','Fila de entrega'],['published','Publicado ou lido']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select></label><button class="btn" type="submit">Filtrar</button></form><p class="hint" data-purchase-count role="status"></p><div class="operation-list" data-purchase-rows></div><div class="actions"><button class="btn secondary" data-purchase-prev>Anterior</button><button class="btn secondary" data-purchase-next>Próxima</button><button class="btn secondary" data-control-route="all">Operar mensagens de vídeo</button><button class="btn secondary" data-control-route="community">Operar Comunidade e LIVE</button><button class="btn secondary" data-control-route="all" data-control-focus="group-messages">Montar telas para edição</button></div></section>`;
 function draw(){if(disposed)return;const result=selectOperations(data,state);if(!result.rows.length&&state.page>0){state.page=0;return draw()}host.querySelector('[data-purchase-rows]').innerHTML=operationRowsMarkup(result.rows);host.querySelector('[data-purchase-count]').textContent=`${result.total} pedidos nesta seleção · página ${state.page+1}${state.query?' · a busca também inclui empresas na aba Todas':''}`;host.querySelector('[data-purchase-prev]').disabled=state.page===0;host.querySelector('[data-purchase-next]').disabled=(state.page+1)*50>=result.total;host.querySelectorAll('[data-open-operation]').forEach(b=>b.onclick=()=>{const row=result.rows.find(r=>r.id===b.dataset.openOperation&&r.kind===b.dataset.operationKind);if(row)onOpen(row)})}
 host.querySelector('[data-purchase-filters]').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.query=String(f.get('query')||'').trim();state.payment=f.get('payment');state.status=f.get('status');state.page=0;delete e.target.dataset.unsaved;draw()};
 host.querySelectorAll('[data-purchase-kind]').forEach(b=>b.onclick=()=>{state.kind=b.dataset.purchaseKind;state.page=0;host.querySelectorAll('[data-purchase-kind]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw()});
 host.querySelector('[data-purchase-prev]').onclick=()=>{state.page=Math.max(0,state.page-1);draw()};host.querySelector('[data-purchase-next]').onclick=()=>{state.page++;draw()};draw();return()=>{disposed=true;host.replaceChildren()};
}
// Move existing nodes, preserving every bound action and field, rather than recreating records.
export function compactOperationCards(host,type){
 host.querySelectorAll('.orders > .order').forEach(card=>{if(card.dataset.compact==='true')return;card.dataset.compact='true';const heading=card.querySelector('.sponsor-review-title strong,.community-admin-identity strong,strong'),name=heading?.textContent||'Pedido',badge=card.querySelector('.badge'),meta=card.querySelector('.meta'),details=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('div');details.className='operation-details';summary.innerHTML='<strong>'+esc(name)+'</strong><span>'+esc(badge?.textContent||'Consultar andamento')+'</span><small>'+esc((meta?.textContent||'').slice(0,200))+'</small><b>Ver detalhes e ações</b>';body.className='operation-detail-body';while(card.firstChild)body.append(card.firstChild);details.append(summary,body);card.append(details);
 const primary=body.querySelector(type==='sponsor'?'[data-sponsor-action="approve"]':type==='community'?'[data-community-action="live_read"],[data-community-action="approve"]':'[data-action="approve"],[data-action="publish"]');if(primary){const quick=document.createElement('div');quick.className='operation-quick-action';quick.append(primary);card.prepend(quick)}
 });
 host.querySelectorAll('aside.settings').forEach(aside=>{if(aside.querySelector('details.control-settings-details'))return;const details=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('div');details.className='control-settings-details';summary.textContent='Configurações desta área';while(aside.firstChild)body.append(aside.firstChild);details.append(summary,body);aside.append(details)});
}
